PAGES=[
 dict(path='news/soda-stereo-ecos-september-13/index.html',slug='soda-stereo-ecos-september-13',title='Soda Stereo ECOS at Dolby Live September 13, 2026',h1='Soda Stereo brings ECOS to Dolby Live September 13.',desc='Soda Stereo brings ECOS to Dolby Live at Park MGM on September 13, 2026. Showtime, venue details and what to know before the Las Vegas concert.',image='/images/news/soda-stereo-ecos-live.jpg',alt='Soda Stereo ECOS live performance',published='2026-05-04',category='Concerts',facts=[('Sept. 13','One Vegas night'),('8 PM','Showtime'),('7 PM','Doors'),('Park MGM','Dolby Live')],lead='Soda Stereo’s ECOS arrives at Dolby Live at Park MGM on Sunday, September 13. Park MGM lists doors at 7 PM and the event at 8 PM.',body=[('What matters now','The original announcement focused on the on-sale. With the concert now days away, that is old news. The useful part is the plan: one Sunday night at Dolby Live, with doors at 7 PM and the show at 8 PM.'),('Why this one is different','Soda Stereo is not a routine nostalgia booking. The band’s catalog has an unusually deep cultural footprint across Latin America, and ECOS is built around that history rather than pretending the past never happened.')],quote='This is the kind of booking that shows how international the Vegas concert calendar has become. You do not need to manufacture urgency around Soda Stereo — for the people this music belongs to, one Las Vegas night is the whole story.',official='https://parkmgm.mgmresorts.com/en/entertainment/soda-stereo.html',official_label='See official event details',address='3770 S Las Vegas Blvd, Las Vegas, NV 89109',faq=[('When is Soda Stereo playing Las Vegas?','Sunday, September 13, 2026 at Dolby Live at Park MGM.'),('What time is Soda Stereo at Dolby Live?','Park MGM lists doors at 7 PM and the event at 8 PM.'),('Where is Dolby Live?','Dolby Live is inside Park MGM at 3770 S Las Vegas Blvd.')]),
 dict(path='news/jo-koy-live-colosseum-caesars-palace-september-19/index.html',slug='jo-koy-live-colosseum-caesars-palace-september-19',title='Jo Koy at Caesars Palace September 19, 2026 | Vegas Sidekick',h1='Jo Koy returns to The Colosseum September 19.',desc='Jo Koy returns to Las Vegas for one night at The Colosseum at Caesars Palace on September 19, 2026. Here is what to know before the show.',image='/images/news/jo-koy-live-colosseum-caesars-palace-september-19-0.webp',alt='Jo Koy Live at The Colosseum at Caesars Palace',published='2026-06-16',category='Comedy',facts=[('Sept. 19','Saturday night'),('8 PM','Showtime'),('1','Vegas show'),('Caesars','The Colosseum')],lead='Jo Koy is back in Las Vegas for one night at The Colosseum at Caesars Palace on Saturday, September 19, with an 8 PM show.',body=[('A Vegas homecoming with a much bigger room','Jo Koy’s connection to Las Vegas predates the arena-scale career. He has talked for years about building his act in local rooms before the worldwide tours, which makes a Colosseum date feel less like a random tour stop and more like a return.'),('Plan around the show, not the old presale','The June on-sale information has done its job and is no longer useful. If you are considering the September 19 show now, check the current ticket inventory and build the evening around Caesars Palace rather than an expired presale clock.')],quote='The part I like about this booking is the full-circle Vegas story. Jo Koy went from working small rooms here to headlining one of the Strip’s signature theaters. The venue is bigger now, but the connection to Las Vegas is not something a tour promoter had to invent.',official='https://www.caesars.com/caesars-palace/shows',official_label='Check Caesars Palace shows',address='3570 S Las Vegas Blvd, Las Vegas, NV 89109',faq=[('When is Jo Koy at Caesars Palace?','Saturday, September 19, 2026.'),('What time is the Jo Koy show?','The event is scheduled for 8 PM.'),('Where is The Colosseum?','The Colosseum is inside Caesars Palace at 3570 S Las Vegas Blvd.')]),
 dict(path='news/backstreet-boys-f1-afterparty-sphere-november-21/index.html',slug='backstreet-boys-f1-afterparty-sphere-november-21',title='Backstreet Boys F1 Afterparty at Sphere Nov. 21, 2026 | Vegas Sidekick',h1='Backstreet Boys headline the F1 Afterparty at Sphere November 21.',desc='Backstreet Boys headline the official Las Vegas Grand Prix F1 Afterparty at Sphere on November 21, 2026. Time, ticket requirements and current package details.',image='/images/news/backstreet-boys-f1-afterparty-sphere-november-21-0.webp',alt='Backstreet Boys for the 2026 F1 Afterparty at Sphere',published='2026-07-17',category='Concerts',facts=[('Nov. 21','Race night'),('11:30 PM','Afterparty'),('Sphere','Las Vegas'),('$116+','Eligible add-on')],lead='The Backstreet Boys will headline the official F1 Afterparty at Sphere on Saturday, November 21, after the Las Vegas Grand Prix. The current official schedule lists the show from 11:30 PM to 1 AM.',body=[('The important ticket detail','This is not a normal standalone Sphere concert ticket. The Las Vegas Grand Prix says a valid 2026 race ticket is required to purchase F1 Afterparty access. Current options include race-plus-afterparty packages and add-ons for eligible race ticketholders.'),('What it costs right now','The official F1 page currently lists the afterparty add-on from $116 for eligible ticketholders. Three-day T-Mobile General Admission plus the afterparty starts at $925, and the T-Mobile Grandstand package plus afterparty starts at $1,560. Those are current official starting prices, not a Vegas Sidekick markup.')],quote='This is exactly the kind of event Vegas is unusually good at: the race is the main event, and then instead of the night ending, thousands of people move into Sphere for Backstreet Boys. I would think of the afterparty as part of the F1 experience, not as a separate concert you happen to squeeze in afterward.',official='https://www.f1lasvegasgp.com/f1-afterparty/',official_label='See official F1 Afterparty options',address='255 Sands Ave, Las Vegas, NV 89169',faq=[('When is the F1 Afterparty at Sphere?','Saturday, November 21, 2026. The official schedule currently lists 11:30 PM to 1 AM.'),('Can I buy an F1 Afterparty ticket without a race ticket?','No. The Las Vegas Grand Prix says a valid race ticket is required to purchase F1 Afterparty access.'),('How much is the F1 Afterparty add-on?','The official page currently lists eligible add-ons from $116. Package pricing varies by race ticket and hotel option.')])
]

CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:#171225;background:#fff;font-family:Inter,sans-serif;line-height:1.68}a{color:inherit;text-decoration:none}img{display:block;max-width:100%}:root{--pink:#ff2e7e;--purple:#6d28d9;--blue:#2477ef;--cyan:#14b8c8;--lime:#d6f33c;--soft:#f6f3fb;--line:#e9e2f1;--muted:#6c6377}.wrap{width:min(1120px,calc(100% - 36px));margin:auto}.progress{position:fixed;top:0;left:0;width:0;height:3px;background:linear-gradient(90deg,var(--lime),var(--cyan),var(--pink));z-index:9999}.hero{background:#130821;color:#fff;overflow:hidden}.hero-grid{display:grid;grid-template-columns:1fr 1fr;min-height:610px}.hero-copy{padding:62px 44px 58px max(28px,calc((100vw - 1120px)/2));display:flex;flex-direction:column;justify-content:center}.crumbs{font-size:.75rem;color:#c7bcd0;margin-bottom:28px}.crumbs span{margin:0 7px;opacity:.55}.eyebrow{font:600 .72rem 'IBM Plex Mono',monospace;text-transform:uppercase;letter-spacing:.14em;color:var(--lime);margin-bottom:13px}h1,h2,h3{font-family:'Plus Jakarta Sans',sans-serif;line-height:1.06;margin:0}h1{font-size:clamp(2.7rem,5.7vw,5rem);letter-spacing:-.055em}.dek{font-size:1.08rem;color:#f0e9f4;max-width:650px;margin:22px 0}.meta{font-size:.82rem;color:#cbbfd1;display:flex;align-items:center;gap:8px;flex-wrap:wrap}.author-inline{display:inline-flex;align-items:center;gap:7px}.author-inline img,.byline img{width:30px;height:30px;border-radius:50%;object-fit:cover}.hero-media{position:relative;min-height:610px}.hero-media img{width:100%;height:100%;object-fit:cover}.hero-media:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,#130821 0,transparent 22%)}.facts{border-bottom:1px solid var(--line)}.facts-grid{display:grid;grid-template-columns:repeat(4,1fr)}.fact{text-align:center;padding:24px 8px;border-right:1px solid var(--line)}.fact:last-child{border:0}.fact strong{display:block;font:800 clamp(1.35rem,3vw,2.15rem) 'Plus Jakarta Sans';color:var(--purple)}.fact span{font-size:.69rem;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}.ticker{overflow:hidden;background:linear-gradient(90deg,#6d28d9,#0d9fb5,#ed337e);color:#fff}.ticker-track{display:flex;width:max-content;animation:ticker 28s linear infinite}.ticker-set{display:flex;white-space:nowrap}.ticker-item{padding:10px 17px;font-size:.78rem;font-weight:800}.ticker-sep{color:var(--lime)}@keyframes ticker{to{transform:translateX(-50%)}}.subnav{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.96);backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}.subnav .wrap{display:flex;gap:22px;overflow:auto;padding:12px 0}.subnav a{font-size:.76rem;font-weight:800;white-space:nowrap;color:#51485c}.article{width:min(780px,calc(100% - 36px));margin:auto;padding:62px 0}.article p{font-size:1.05rem;margin:0 0 22px}.lead{font-size:1.25rem!important;font-weight:700;line-height:1.6}.article h2{font-size:clamp(2rem,4vw,3rem);letter-spacing:-.04em;margin:58px 0 18px}.take{background:linear-gradient(135deg,#17082e,#3d1253);color:#fff;border-radius:20px;padding:28px;margin:34px 0}.take .take-head{display:flex;align-items:center;gap:10px;color:var(--lime);font:800 1rem 'Plus Jakarta Sans'}.take .take-head img{width:30px;height:30px;border-radius:50%;object-fit:cover}.take blockquote{font-size:1.08rem;margin:14px 0 10px;color:#f1e8f4}.take cite{font-style:normal;font-size:.82rem;color:#cfc1d5}.official{display:inline-flex;align-items:center;justify-content:center;background:var(--blue);color:#fff;border-radius:10px;padding:13px 18px;font-weight:800;margin-top:8px}.signup{margin:42px 0;padding:30px;border-radius:22px;background:linear-gradient(135deg,#17082e,#341253 56%,#102d43);color:#fff}.signup h3{font-size:clamp(1.55rem,4vw,2.25rem);margin:0 0 10px}.signup p{color:#e7ddeb}.signup form{display:flex;gap:9px}.signup input{flex:1;min-width:0;border:1px solid rgba(255,255,255,.24);background:rgba(255,255,255,.1);color:#fff;border-radius:10px;padding:13px 14px;font:inherit}.signup button{border:0;border-radius:10px;background:var(--lime);color:#171225;font-weight:800;padding:13px 17px}.faq{display:grid;gap:11px;margin-top:24px}.faq details{border:1px solid var(--line);border-left:6px solid var(--purple);border-radius:13px;overflow:hidden}.faq summary{cursor:pointer;list-style:none;font-weight:800;padding:18px 20px}.faq p{padding:0 20px 20px;margin:0;color:#5d5468}.utility{background:var(--soft);padding:68px 0}.utility-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:24px}.utility-card{background:#fff;border:1px solid var(--line);border-radius:15px;padding:23px}.utility-card b{display:block;font-family:'Plus Jakarta Sans';margin-bottom:7px}.utility-card p{margin:0;font-size:.9rem;color:var(--muted)}.byline{margin-top:34px;font-size:.88rem;color:#494052}.final{background:#160927;color:#fff;padding:58px 0}.final-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:30px;align-items:center}.final h2{font-size:clamp(2rem,4vw,3.3rem)}.final p{color:#ddd1e2}.final .official{width:100%;background:linear-gradient(90deg,var(--cyan),var(--blue));border:2px solid #fff}@media(max-width:800px){.hero-grid{grid-template-columns:1fr}.hero-media{order:-1;min-height:360px;max-height:430px}.hero-copy{padding:38px 22px 44px}.hero-media:after{background:linear-gradient(0deg,#130821 0,transparent 30%)}.facts-grid{grid-template-columns:repeat(2,1fr)}.fact:nth-child(2){border-right:0}.fact:nth-child(-n+2){border-bottom:1px solid var(--line)}.utility-grid,.final-grid{grid-template-columns:1fr}.article{padding-top:46px}.signup form{flex-direction:column}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.ticker-track{animation:none}}'''

def render(d):
    canonical='https://vegassidekick.com/news/'+d['slug']+'/'
    image_abs='https://vegassidekick.com'+d['image']
    faq_schema=[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in d['faq']]
    schema={'@context':'https://schema.org','@graph':[{'@type':'NewsArticle','headline':d['h1'].rstrip('.'),'description':d['desc'],'image':[image_abs],'datePublished':d['published'],'dateModified':'2026-09-06','author':{'@type':'Person','@id':'https://vegassidekick.com/about/kris-kidd/#kris','name':'Kris Kidd','url':'https://vegassidekick.com/about/kris-kidd/','image':'https://vegassidekick.com/images/kris-kidd.webp'},'publisher':{'@type':'Organization','name':'Vegas Sidekick','url':'https://vegassidekick.com/'},'mainEntityOfPage':{'@type':'WebPage','@id':canonical},'articleSection':'Vegas Dispatch'},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':'https://vegassidekick.com/'},{'@type':'ListItem','position':2,'name':'Vegas Dispatch','item':'https://vegassidekick.com/news/'},{'@type':'ListItem','position':3,'name':d['h1'].rstrip('.'),'item':canonical}]},{'@type':'FAQPage','mainEntity':faq_schema}]}
    facts=''.join(f'<div class="fact"><strong>{a}</strong><span>{b}</span></div>' for a,b in d['facts'])
    ticker=''.join(f'<span class="ticker-item">{a.upper()} <span class="ticker-sep">✦</span></span>' for a,b in d['facts'])
    body=''.join(f'<h2 id="s{i}">{h}</h2><p>{p}</p>' for i,(h,p) in enumerate(d['body'],1))
    faq=''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in d['faq'])
    return f'''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{d['title']}</title><meta name="robots" content="index,follow,max-image-preview:large"><meta name="description" content="{d['desc']}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="article"><meta property="og:site_name" content="Vegas Sidekick"><meta property="og:title" content="{d['h1']}"><meta property="og:description" content="{d['desc']}"><meta property="og:image" content="{image_abs}"><meta property="og:image:alt" content="{d['alt']}"><meta property="og:url" content="{canonical}"><meta property="article:published_time" content="{d['published']}T08:00:00-07:00"><meta property="article:modified_time" content="2026-09-06T20:00:00-07:00"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{d['h1']}"><meta name="twitter:description" content="{d['desc']}"><meta name="twitter:image" content="{image_abs}"><link rel="preload" as="image" href="{d['image']}" fetchpriority="high"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Plus+Jakarta+Sans:wght@600;700;800&family=IBM+Plex+Mono:wght@500;600&display=swap" rel="stylesheet"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False,separators=(',',':'))}</script><style>{CSS}</style></head><body><div class="progress" id="progress"></div><div id="vs-header"></div><header class="hero"><div class="hero-grid"><div class="hero-copy"><div class="crumbs"><a href="/">Vegas Sidekick</a><span>›</span><a href="/news/">Vegas Dispatch</a></div><div class="eyebrow">Vegas Dispatch · {d['category']}</div><h1>{d['h1']}</h1><p class="dek">{d['desc']}</p><div class="meta"><span class="author-inline"><img src="/images/kris-kidd.webp" alt="Kris Kidd"><a href="/about/kris-kidd/"><strong>Kris Kidd</strong></a></span><span>· Updated Sept. 6, 2026</span></div></div><div class="hero-media"><img src="{d['image']}" alt="{d['alt']}"></div></div></header><section class="facts"><div class="wrap facts-grid">{facts}</div></section><div class="ticker"><div class="ticker-track"><div class="ticker-set">{ticker}</div><div class="ticker-set" aria-hidden="true">{ticker}</div></div></div><nav class="subnav"><div class="wrap"><a href="#details">What to know</a><a href="#take">Kris's take</a><a href="#faq">FAQ</a></div></nav><main class="article"><p class="lead" id="details">{d['lead']}</p>{body}<div class="take" id="take"><div class="take-head"><img src="/images/kris-kidd.webp" alt="Kris Kidd">🌵 Kris's take</div><blockquote>“{d['quote']}”</blockquote><cite>— Kris Kidd, founder of Vegas Sidekick · Las Vegas local since 2005 · in show ticketing since 2006</cite></div><a class="official" href="{d['official']}" rel="noopener">{d['official_label']} →</a><div class="signup"><div class="eyebrow">The Spike Insider List</div><h3>Vegas changes fast. I keep the useful stuff.</h3><p>New openings, show changes and Vegas updates worth knowing.</p><form action="https://brevo-subscribe.vegassidekickcom.workers.dev" method="post"><input type="email" name="email" placeholder="you@example.com" aria-label="Email address" required><button type="submit">Join the list</button></form></div><h2 id="faq">Quick questions</h2><div class="faq">{faq}</div><p class="byline"><img src="/images/kris-kidd.webp" alt="Kris Kidd"> By <a href="/about/kris-kidd/"><strong>Kris Kidd</strong></a> · Las Vegas local since 2005, in show ticketing since 2006. Updated September 6, 2026.</p></main><section class="utility"><div class="wrap"><div class="eyebrow" style="color:var(--purple)">Still planning?</div><h2>Make the next click useful.</h2><div class="utility-grid"><a class="utility-card" href="/news/"><b>Read Vegas Dispatch →</b><p>New openings, announcements and changes worth knowing.</p></a><a class="utility-card" href="/guides/"><b>Browse show guides →</b><p>Start with the kind of Vegas night you actually want.</p></a><a class="utility-card" href="/shows/"><b>Browse Vegas shows →</b><p>Compare resident shows around the Strip.</p></a></div></div></section><section class="final"><div class="wrap final-grid"><div><div class="eyebrow">Official event information</div><h2>{d['h1']}</h2><p>{d['address']}</p></div><a class="official" href="{d['official']}" rel="noopener">{d['official_label']} →</a></div></section><div id="vs-footer"></div><script src="/components/header.js?v=13"></script><script src="/components/footer.js?v=10"></script><script>const bar=document.getElementById('progress');addEventListener('scroll',()=>{{const h=document.documentElement.scrollHeight-innerHeight;bar.style.width=(h>0?scrollY/h*100:0)+'%'}},{{passive:true}});</script></body></html>'''

for d in PAGES:
    p=Path(d['path']); assert p.exists(), d['path']; p.write_text(render(d),encoding='utf-8')
print('rebuilt',len(PAGES),'Dispatch pages')